begin;
insert into auth.users values('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into auth.sessions values('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111',now()+interval '1 hour');
set local role service_role;
do $$declare c jsonb;w uuid;j jsonb;t jsonb;r jsonb;old_claim uuid;report jsonb;begin
  c=public.begin_wallet_challenge('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444',null,'http://localhost:5182',repeat('A',43)||'=');
  w=public.bind_owned_wallet('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',(c->>'id')::uuid,'fictional.testnet','ed25519:'||repeat('1',32),repeat('a',64));
  if (select count(*) from public.game_player_wallets)<>0 or (select count(*) from vault.secrets)<>0 then raise exception 'Player key was allocated'; end if;
  begin
    perform public.register_game_wallet(w,'11111111-1111-4111-8111-111111111111','ed25519:'||repeat('1',32),'ed25519:'||repeat('1',64));
    raise exception 'A custodial wallet was allocated';
  exception when insufficient_privilege then null;end;
  if (select count(*) from vault.secrets)<>0 then raise exception 'A rejected player key left an orphan secret';end if;
  if w<>public.bind_owned_wallet('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',(c->>'id')::uuid,'fictional.testnet','ed25519:'||repeat('1',32),repeat('a',64)) then raise exception 'Wallet proof was not idempotent'; end if;
  begin perform public.bind_owned_wallet('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333',(c->>'id')::uuid,'other.testnet','ed25519:'||repeat('1',32),repeat('a',64));raise exception 'Cross-owner proof succeeded';exception when insufficient_privilege then null;end;
  update public.game_worlds set status='ready',contract_id='shop.fictional.testnet' where id=w;
  t=public.begin_npc_turn('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',repeat('b',64));
  if (t->>'claimed')::boolean is not true then raise exception 'Turn not claimed'; end if;
  r=public.begin_npc_turn('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',repeat('b',64));
  if (r->>'claimed')::boolean then raise exception 'Turn claimed twice'; end if;
  old_claim=(t->>'claim_id')::uuid;
  update public.game_npc_turns set lease_until=now()-interval '1 second';
  t=public.begin_npc_turn('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',repeat('b',64));
  if not (t->>'claimed')::boolean or (t->>'claim_id')::uuid=old_claim then raise exception 'Expired turn was not fenced';end if;
  if public.finish_npc_turn('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',old_claim,'{"messages":[]}','{}',null) then raise exception 'Stale worker changed history';end if;
  update public.game_npc_budget set request_limit=1,token_limit=3000;
  j=public.reserve_npc_judgment('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',repeat('c',64));
  if not (j->>'claimed')::boolean then raise exception 'Judgment not reserved'; end if;
  r=public.reserve_npc_judgment('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',repeat('c',64));
  if (r->>'claimed')::boolean then raise exception 'Model call reserved twice'; end if;
  if not public.finish_npc_judgment(w,'55555555-5555-4555-8555-555555555555',(j->>'claim_id')::uuid,'{"usage":{"input_tokens":450}}') then raise exception 'Usage not saved'; end if;
  perform public.finish_npc_judgment(w,'55555555-5555-4555-8555-555555555555',(j->>'claim_id')::uuid,'{"usage":{"input_tokens":450}}');
  if (select tokens_used from public.game_npc_budget)<>450 or (select tokens_reserved from public.game_npc_budget)<>0 then raise exception 'Duplicate usage counted'; end if;
  begin perform public.reserve_npc_judgment('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'66666666-6666-4666-8666-666666666666',repeat('c',64));raise exception 'Expected budget exhaustion';exception when raise_exception then if sqlerrm<>'Jev playtest allowance exhausted' then raise;end if;end;
  if not public.finish_npc_turn('11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',w,'55555555-5555-4555-8555-555555555555',(t->>'claim_id')::uuid,'{"messages":[],"turn":1}','{"ok":true}',null) then raise exception 'Turn was not finished'; end if;
  perform public.ensure_arena_runtime('ar-'||repeat('a',32)||'.testnet','ed25519:'||repeat('1',64));
  perform public.ensure_arena_runtime('ar-'||repeat('b',32)||'.testnet','ed25519:'||repeat('2',64));
  if (select count(*) from public.game_arena_runtime)<>1 or (select count(*) from vault.secrets)<>1 then raise exception 'Referee allocated twice';end if;
  if not public.claim_arena_faucet() or public.claim_arena_faucet() then raise exception 'Referee faucet repeated';end if;
  r=public.save_arena_setup('saved-bytes','saved-hash');r=public.save_arena_setup('different-bytes','different-hash');
  if r->>'signed_tx'<>'saved-bytes' then raise exception 'Setup transaction overwritten';end if;
  report='{"match_id":"77777777-7777-4777-8777-777777777777","players":["fictional.testnet","other.testnet"],"expected_xp":[0,0]}';
  begin perform public.claim_duel_report('77777777-7777-4777-8777-777777777777',report);raise exception 'Unverified report was accepted';exception when insufficient_privilege then null;end;
  update public.game_arena_state set state=state||jsonb_build_object('settlements',jsonb_build_object('77777777-7777-4777-8777-777777777777',jsonb_build_object('result',report)));
  j=public.claim_duel_report('77777777-7777-4777-8777-777777777777',report);
  if not (j->>'claimed')::boolean then raise exception 'Completed duel not claimed';end if;
  r=public.claim_duel_report('77777777-7777-4777-8777-777777777777',report);
  if (r->>'claimed')::boolean then raise exception 'Duel claimed twice';end if;
  if not public.save_duel_transaction('77777777-7777-4777-8777-777777777777',(j->>'claim_id')::uuid,'saved-referee-bytes','saved-referee-hash') then raise exception 'Duel payload not saved';end if;
  if public.save_duel_transaction('77777777-7777-4777-8777-777777777777',(j->>'claim_id')::uuid,'different-referee-bytes','different-referee-hash') then raise exception 'Duel payload overwritten';end if;
  perform public.confirm_duel_report('77777777-7777-4777-8777-777777777777',report);
  if (select status from public.game_duel_outbox)<>'confirmed' then raise exception 'Receipt was not confirmed';end if;
end$$;
reset role;
do $$declare t text;begin
  foreach t in array array['game_owned_wallets','game_wallet_challenges','game_npc_threads','game_npc_turns','game_npc_judgments','game_npc_budget','game_gas_grants','game_arena_runtime','game_duel_outbox'] loop
    if has_table_privilege('authenticated','public.'||t,'select') or has_table_privilege('anon','public.'||t,'select') then raise exception 'Private table exposed: %',t; end if;
    if not (select relrowsecurity from pg_class where oid=('public.'||t)::regclass) then raise exception 'RLS missing: %',t;end if;
  end loop;
  if has_function_privilege('authenticated','public.bind_owned_wallet(uuid,uuid,uuid,text,text,text)','execute') then raise exception 'Wallet RPC exposed';end if;
end$$;
rollback;
